<?php require_once __DIR__ . '/../bootstrap.php'; $input=body(); $identifier=clean($input['identifier']??''); $stmt=$pdo->prepare('SELECT * FROM users WHERE email=? OR username=? LIMIT 1'); $stmt->execute([$identifier,$identifier]); $user=$stmt->fetch(); if(!$user||$user['status']!=='active'||!password_verify($input['password']??'', $user['password']??'')) respond(false,$user&&$user['status']!=='active'?'Your account has been disabled.':'Invalid email or password.',[],401); $pdo->prepare('UPDATE users SET last_login=NOW() WHERE id=?')->execute([$user['id']]); unset($user['password']); $_SESSION['user']=$user; respond(true,'Signed in successfully.',['user'=>$user]);
